  "inlineSchema": "datasource db {\n  provider = \"postgresql\"\n  url      = env(\"DATABASE_URL\")\n}\n\ngenerator client {\n  provider = \"prisma-client-js\"\n}\n\n// ==========================================\n// USER & AUTHENTICATION\n// ==========================================\nmodel User {\n  id           String   @id @default(uuid())\n  name         String\n  email        String   @unique\n  passwordHash String\n  createdAt    DateTime @default(now())\n  updatedAt    DateTime @updatedAt\n\n  wallets       Wallet[]\n  refreshTokens RefreshToken[]\n\n  // Relations for Invoices\n  createdInvoices Invoice[] @relation(\"InvoiceCreator\")\n  payerInvoices   Invoice[] @relation(\"InvoicePayer\")\n}\n\nmodel RefreshToken {\n  id        String   @id @default(uuid())\n  token     String   @unique\n  userId    String\n  user      User     @relation(fields: [userId], references: [id], onDelete: Cascade)\n  expiresAt DateTime\n  createdAt DateTime @default(now())\n}\n\n// ==========================================\n// CORE LEDGER & WALLET\n// ==========================================\nmodel Wallet {\n  id        String   @id @default(uuid())\n  userId    String\n  user      User     @relation(fields: [userId], references: [id])\n  currency  String   @default(\"USD\")\n  balance   Decimal  @default(0.00)\n  isActive  Boolean  @default(true)\n  createdAt DateTime @default(now())\n  updatedAt DateTime @updatedAt\n\n  entries Entry[]\n  cards   Card[]\n}\n\nmodel Transaction {\n  id             String   @id @default(uuid())\n  idempotencyKey String?  @unique\n  type           TxType\n  status         TxStatus @default(PENDING)\n  amount         Decimal\n  createdAt      DateTime @default(now())\n\n  entries Entry[]\n  invoice Invoice? // Transação pode estar vinculada ao pagamento de uma fatura\n}\n\nmodel Entry {\n  id            String      @id @default(uuid())\n  transactionId String\n  transaction   Transaction @relation(fields: [transactionId], references: [id])\n  walletId      String\n  wallet        Wallet      @relation(fields: [walletId], references: [id])\n  type          EntryType\n  amount        Decimal\n  createdAt     DateTime    @default(now())\n}\n\n// ==========================================\n// MODULE 1: VIRTUAL CARDS (NOVO)\n// ==========================================\nmodel Card {\n  id              String     @id @default(uuid())\n  walletId        String\n  wallet          Wallet     @relation(fields: [walletId], references: [id])\n  cardNumberLast4 String // Apenas guardamos os últimos 4 dígitos por segurança (PCI DSS)\n  expiryMonth     Int\n  expiryYear      Int\n  status          CardStatus @default(ACTIVE)\n  type            CardType   @default(VIRTUAL)\n  dailyLimit      Decimal?\n  createdAt       DateTime   @default(now())\n  updatedAt       DateTime   @updatedAt\n}\n\n// ==========================================\n// MODULE 2: INVOICES / PAYMENT REQUESTS (NOVO)\n// ==========================================\nmodel Invoice {\n  id String @id @default(uuid())\n\n  creatorId String\n  creator   User   @relation(\"InvoiceCreator\", fields: [creatorId], references: [id])\n\n  payerEmail String? // Útil caso a cobrança seja para alguém fora do sistema\n  payerId    String?\n  payer      User?   @relation(\"InvoicePayer\", fields: [payerId], references: [id])\n\n  amount      Decimal\n  description String?\n  status      InvoiceStatus @default(PENDING)\n  dueDate     DateTime?\n\n  // Quando for paga, é gerada uma Transaction no Ledger e vinculada aqui\n  transactionId String?      @unique\n  transaction   Transaction? @relation(fields: [transactionId], references: [id])\n\n  createdAt DateTime @default(now())\n  updatedAt DateTime @updatedAt\n}\n\n// ==========================================\n// SYSTEM (IDEMPOTENCY & WEBHOOKS)\n// ==========================================\nmodel IdempotencyRecord {\n  key          String   @id\n  path         String\n  method       String\n  responseCode Int\n  responseBody Json\n  createdAt    DateTime @default(now())\n}\n\nmodel WebhookEndpoint {\n  id        String   @id @default(uuid())\n  url       String\n  secret    String\n  isActive  Boolean  @default(true)\n  createdAt DateTime @default(now())\n\n  deliveries WebhookDelivery[]\n}\n\nmodel WebhookDelivery {\n  id                String          @id @default(uuid())\n  webhookEndpointId String\n  webhookEndpoint   WebhookEndpoint @relation(fields: [webhookEndpointId], references: [id], onDelete: Cascade)\n  payload           Json\n  responseCode      Int?\n  status            String // SUCCESS / FAILED\n  createdAt         DateTime        @default(now())\n}\n\n// ==========================================\n// ENUMS\n// ==========================================\nenum TxType {\n  DEPOSIT\n  TRANSFER\n  WITHDRAWAL\n  INVOICE_PAYMENT // Novo tipo de transação\n  CARD_PURCHASE // Novo tipo de transação\n}\n\nenum TxStatus {\n  PENDING\n  COMPLETED\n  FAILED\n  REFUNDED // Adicionado para estornos de cartão\n}\n\nenum EntryType {\n  CREDIT\n  DEBIT\n}\n\nenum CardStatus {\n  ACTIVE\n  BLOCKED\n  CANCELLED\n}\n\nenum CardType {\n  VIRTUAL\n  PHYSICAL\n}\n\nenum InvoiceStatus {\n  PENDING\n  PAID\n  CANCELLED\n  OVERDUE\n}\n",
